    const world = game.world, d = world.l7Departure!, bus = world.entities.get(d.state.busId)!;
    return { tick: world.tick, elapsed: (world.tick - d.state.startedAt) / 60, phase: d.state.phase, bus: { x: bus.transform.x, z: bus.transform.z }, soldiers: [...world.entities.iterate()].filter(e => e.civilian?.ally?.role === 'soldier').map(e => ({ id: e.id, x: e.transform.x, z: e.transform.z, hidden: e.hidden })) };
  });
  await session.screenshot(`${out}/high-z1-0.7s.png`);
  await session.page.evaluate(async () => { await window.__SS__!.step(162); });
  const at34 = await session.page.evaluate(() => {
    const game = (window.__SCENE__ as unknown as { game: import('/Users/wesner/Workspace/minorincident/.claude/worktrees/s108-leftovers/src/Game').Game }).game;
    const world = game.world, d = world.l7Departure!, bus = world.entities.get(d.state.busId)!;
    return { tick: world.tick, elapsed: (world.tick - d.state.startedAt) / 60, phase: d.state.phase, bus: { x: bus.transform.x, z: bus.transform.z }, soldiers: [...world.entities.iterate()].filter(e => e.civilian?.ally?.role === 'soldier').map(e => ({ id: e.id, x: e.transform.x, z: e.transform.z, hidden: e.hidden })) };
  });
  await session.screenshot(`${out}/high-z1-3.4s.png`);
