const out='/Users/wesner/Workspace/minorincident/.claude/worktrees/s108-leftovers/test-results/s108-leftovers'; const rows=[];
for(const tier of ['high','low'] as const)for(const weapon of ['weapon.shotgun','weapon.nail-gun']) {
const w=await loadLevel('L10',3,undefined,0,{quality:tier});w.missions!.loadResume(JSON.parse(readFileSync(`${out}/${tier}-destroyed-corridor-resume.json`,'utf8')));const p=w.entities.get(1)!,boss=w.megaPursuit!.entity()!;w.combat!.damage.god=true;
const def=w.combat!.runner.loadout.definition(weapon);const hits:any[]=[],attacks:any[]=[],health:any[]=[];w.events.on('combat.hit',(e:any)=>{if(e.targetId===boss.id)hits.push({...e,hp:boss.health.current});});w.events.on('combat.attack',(e:any)=>{if(e.sourceId===1)attacks.push(e);});
const start={player:{...p.transform},boss:{...boss.transform},hp:boss.health.current,weapon,definition:def,racks:p.weapons};let lastHp=boss.health.current;
for(let i=0;i<1800;i++){const b=w.megaPursuit!.entity()!,dx=b.transform.x-p.transform.x,dz=b.transform.z-p.transform.z,d=Math.hypot(dx,dz),f=emptyInput();const ix=p.weapons!.RIGHT.rack.findIndex(s=>s.id===weapon);if(ix<0)throw Error('missing weapon');f.selectedSlot={side:'RIGHT',index:ix};f.aimSource='keyboard';f.aim={x:dx/d,z:dz/d};f.aimPoint={x:b.transform.x,z:b.transform.z};f.right.held=i<1500; if(d>4)f.move={x:dx/d,z:dz/d};else if(d<2)f.move={x:-dx/d,z:-dz/d};w.applyInput(f,'keyboard');w.update();if(b.health.current!==lastHp){health.push({tick:w.tick,hp:b.health.current});lastHp=b.health.current;}}
rows.push({tier,weapon,start,hits,attacks,health,end:{hp:boss.health.current,player:{...p.transform},boss:{...boss.transform}}});w.dispose();writeFileSync(`${out}/guns-native.json`,JSON.stringify(rows));console.log(tier,weapon,hits.length,health.length);
}

